  window.addEventListener("DOMContentLoaded", (event) => {
    // Split text into spans
    let typeSplit = new SplitType("[text-split]", {
      types: "words, chars",
      tagName: "span",
      wordClass: "word",
      charClass: "char",
    });

    // Add spaces after each word span to fix spacing issue and set line height
    document
      .querySelectorAll("[text-split] .word")
      .forEach((word, index, words) => {
        if (index < words.length - 1) {
          word.style.marginRight = "0.15em";
        }
      });

    // Set line height for text-split elements
    document.querySelectorAll("[text-split]").forEach((element) => {
      element.style.lineHeight = "1.4"; // Adjust this value as needed
    });

    // Link timelines to scroll position
    function createScrollTrigger(triggerElement, timeline) {
      // Reset tl when scroll out of view past bottom of screen
      ScrollTrigger.create({
        trigger: triggerElement,
        start: "top bottom",
        onLeaveBack: () => {
          timeline.progress(0);
          timeline.pause();
        },
      });
      // Play tl when scrolled into view (60% from top of screen)
      ScrollTrigger.create({
        trigger: triggerElement,
        start: "top 60%",
        onEnter: () => timeline.play(),
      });
    }
    $("[words-slide-from-right]").each(function (index) {
      let tl = gsap.timeline({ paused: true });
      tl.from($(this).find(".word"), {
        opacity: 0,
        x: "1em",
        duration: 0.6,
        ease: "power2.out",
        stagger: { amount: 0.2 },
      });
      createScrollTrigger($(this), tl);
    });
    // Avoid flash of unstyled content
    gsap.set("[text-split]", { opacity: 1 });
  });
